#!/usr/bin/env bash
# Build the Chrome Web Store package (store/ecosphere-assistant-cws.zip).
#
# NEVER ship these — they are gitignored because they are secrets or machine
# specific, and a previous package leaked them:
#   native/key.pem     a private key (nothing in the extension consumes it)
#   native/config.json generated by native/install.sh, holds the developer's
#                      absolute paths (/Users/<dev>/...)
#   native/host        generated launcher, same problem
# native/install.sh re-creates config.json + host on the user's own machine.
set -euo pipefail
cd "$(dirname "$0")/.."

out="store/ecosphere-assistant-cws.zip"
rm -f "$out"
zip -q -r "$out" \
  manifest.json \
  background.js \
  estate-detect.js \
  sidepanel.html sidepanel.js sidepanel.css \
  helper-install.command \
  icons \
  native/host.js native/install.sh native/install.command native/uninstall.sh native/build-helper.sh

echo "built $out"
unzip -l "$out"
